using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Admin.Client;
using PhoneStore.Infrastructure.Data;

namespace PhoneStore.Admin.Client.Checks;

internal static class ReportChecks
{
    private static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
    public static async Task Run()
    {
        await using var qa=await QaBackend.Create();var gate=new SupplyRaceGate();qa.CommandInterceptor=gate;var probe=new ReportProbe();using var api=qa.Api(probe);await api.LoginAsync("admin-w1-qa",qa.Password);
        var catalog=new CatalogWorkspace(api);var supply=new SupplyWorkspace(api);var orders=new OrdersWorkspace(api);var reports=new ReportsWorkspace(api);await using var db=qa.Open();var records=new List<object>();
        async Task<object> State()=>new{stock=await db.Inventory.AsNoTracking().OrderBy(x=>x.VariantId).Select(x=>new{x.VariantId,H=x.OnHand,R=x.Reserved,Available=x.OnHand-x.Reserved}).ToListAsync(),orders=await db.Orders.AsNoTracking().OrderBy(x=>x.Id).ToListAsync(),payments=await db.Payments.AsNoTracking().OrderBy(x=>x.OrderId).ToListAsync(),history=await db.OrderHistory.AsNoTracking().OrderBy(x=>x.Id).ToListAsync(),journal=await db.Movements.AsNoTracking().OrderBy(x=>x.Id).ToListAsync()};
        async Task Step(string id,string name,Func<Task> run){var before=await State();await run();records.Add(new{id,name,status="PASS",before,after=await State()});Console.WriteLine("PASS "+id+" "+name);}
        var brand=(await catalog.SaveLookup("brands",0,new("Hãng W6 QA",true))).Single().Id;var category=(await catalog.SaveLookup("categories",0,new("Điện thoại W6 QA",true))).Single().Id;
        var product=await catalog.Save(0,new("W6-PHONE","Điện thoại báo cáo QA",brand,category,"QA","QA","",true,[new(0,"W6-A","Đen",128,10000000,20,true,null),new(0,"W6-B","Trắng",256,12000000,25,true,null)],[]));var a=product.Variants[0].Id;var b=product.Variants[1].Id;
        var supplier=await new ContactsWorkspace(api).SaveSupplier(0,new("W6-SUP","NCC W6 QA","0938123593","QA isolated",true));
        await Step("WIN.FLOW.01","UI01/UI08/UI09 client purchase creates stock20/20; authoritative prices",async()=>{var draft=await new PurchaseDraftSession(api).Save(supplier.Id,[new(a,20,8000000),new(b,20,10000000)]);var confirmed=await supply.Execute(new(draft.Purchase,"confirm"));Check(confirmed.CurrentStock.All(x=>x.Stock.OnHand==20&&x.Stock.Reserved==0)&&confirmed.CurrentStock.Single(x=>x.Stock.VariantId==a).Price==9600000&&confirmed.CurrentStock.Single(x=>x.Stock.VariantId==b).Price==12500000,"Receipt balance/price mismatch");});
        using var customer=qa.CreateClient(new(){BaseAddress=new("https://localhost")});
        async Task<HttpResponseMessage> Post(string path,object body){var token=await customer.GetFromJsonAsync<TokenResult>("/api/security/token");using var request=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(body)};request.Headers.Add("X-CSRF-TOKEN",token!.Token);return await customer.SendAsync(request);}
        using(var login=await Post("/api/auth/login",new{username="customer-w1-qa",password=qa.Password,surface="customer"}))Check(login.IsSuccessStatusCode,"Customer login failed");
        async Task<AdminOrder> New(bool both=false){foreach(var line in both?new[]{new{variantId=a,quantity=1},new{variantId=b,quantity=2}}:new[]{new{variantId=a,quantity=1}}){using var add=await Post("/api/cart",line);Check(add.IsSuccessStatusCode,"Cart failed");}using var create=await Post("/api/orders",new{requestKey=Guid.NewGuid(),recipient="W6 QA",phone="0938123591",address="QA isolated",paymentMethod="COD",lines=both?new[]{new{variantId=a,quantity=1,price=9600000},new{variantId=b,quantity=2,price=12500000}}:new[]{new{variantId=a,quantity=1,price=9600000}}});Check(create.StatusCode==HttpStatusCode.Created,"Checkout failed");return await orders.Read((await create.Content.ReadFromJsonAsync<Created>())!.Id);}
        AdminOrder row=null!;
        await Step("WIN.FLOW.01","checkout reserves1/2 without changing H; total34.600.000",async()=>{row=await New(true);Check(row.Total==34600000,"Checkout total mismatch");Check((await supply.StockRow(a,"W6-A")) is {OnHand:20,Reserved:1,Available:19}&&(await supply.StockRow(b,"W6-B")) is {OnHand:20,Reserved:2,Available:18},"Checkout H/R mismatch");});
        foreach(var action in new[]{OrderAction.Confirm,OrderAction.Dispatch,OrderAction.Complete})await Step("WIN.FLOW.01",action.ToString(),async()=>{row=await orders.Execute(new(row,action));Check(row.Payment==(action==OrderAction.Complete?"DA_THU":"CHUA_THU"),"COD state mismatch");var stock=await supply.StockRow(a,"W6-A");Check(stock.OnHand==(action==OrderAction.Confirm?20:19)&&stock.Reserved==(action==OrderAction.Confirm?1:0),"FLOW01 balance mismatch");});
        var today=ReportPresentation.Today();
        await Step("WIN.A22.01/02/03/04/05/06","same report source; variant bestsellers; monthly sums; readonly report/empty/error",async()=>{var before=JsonSerializer.Serialize(await State());var report=await reports.Read("revenue",today,today);Check(report.Revenue==34600000&&report.Orders==1&&report.Quantity==3&&report.Daily.Sum(x=>x.Revenue)==34600000,"Revenue/line double counting");var monthly=ReportPresentation.Project(report,true);Check(ReferenceEquals(monthly.Source,report)&&monthly.Points.Sum(x=>x.Value)==34600000&&monthly.Rows.Sum(x=>x.Revenue)==34600000,"Monthly source mismatch");var best=await reports.Read("bestsellers",today,today);Check(best.Bestsellers.Count==2&&best.Bestsellers.Select(x=>x.VariantId).Distinct().Count()==2&&best.Bestsellers.Sum(x=>x.Revenue)==34600000,"Variant bestseller grouping wrong");var stock=await reports.Read("stock",today.AddDays(4),today);Check(stock.Stock.Single(x=>x.VariantId==a) is {OnHand:19,Reserved:0,Available:19}&&!probe.Paths.Last().Contains("from="),"Stock used date or wrong balances");var empty=await reports.Read("revenue",today.AddDays(2),today.AddDays(2));Check(empty.Revenue==0&&empty.Daily.Count==0,"Empty report wrong");var calls=probe.Paths.Count;foreach(var dates in new[]{((DateOnly?)null,(DateOnly?)today),((DateOnly?)today,(DateOnly?)null),((DateOnly?)today,(DateOnly?)today.AddDays(-1))}){try{await reports.Read("revenue",dates.Item1,dates.Item2);throw new InvalidOperationException("Dates accepted");}catch(AdminApiException e){Check(e.Code=="INVALID_INPUT","Date error wrong");}}Check(probe.Paths.Count==calls,"Invalid dates sent HTTP");gate.FailStockReads=true;try{await reports.Read("stock");throw new InvalidOperationException("DB error became zero");}catch(AdminApiException e){Check(e.Code=="SERVER_ERROR"&&e.Status==500&&gate.StockFailureSeen,"Real SQL read failure not surfaced");}finally{gate.FailStockReads=false;}Check(before==JsonSerializer.Serialize(await State()),"Reports modified commerce");});
        await Step("WIN.FLOW.02","failed delivery does not return stock; return once; cancel confirmed releases R",async()=>{row=await New();row=await orders.Execute(new(row,OrderAction.Confirm));row=await orders.Execute(new(row,OrderAction.Dispatch));row=await orders.Execute(new(row,OrderAction.Fail,"Khách không nhận QA"));Check((await supply.StockRow(a,"W6-A")) is {OnHand:18,Reserved:0},"Fail returned stock early");row=await orders.Execute(new(row,OrderAction.ReceiveReturn));Check((await supply.StockRow(a,"W6-A")).OnHand==19&&row.Payment=="CHUA_THU","Return mismatch");var before=JsonSerializer.Serialize(await State());try{await orders.Execute(new(row,OrderAction.ReceiveReturn));throw new InvalidOperationException("Repeated return accepted");}catch(AdminApiException e){Check(e.Code=="INVALID_STATE","Repeat error wrong");}Check(before==JsonSerializer.Serialize(await State()),"Repeat changed stock");row=await New();row=await orders.Execute(new(row,OrderAction.Confirm));row=await orders.Execute(new(row,OrderAction.Cancel,"Hủy QA"));Check((await supply.StockRow(a,"W6-A")) is {OnHand:19,Reserved:0}&&row.Payment=="CHUA_THU","Cancel mismatch");});
        await Step("WIN.A22.01/03","UTC+7 inclusive final-day boundaries; completedAt and COD collectedAt fixture timestamps",async()=>{var day=new DateOnly(2026,6,10);var start=new DateTime(2026,6,9,17,0,0,DateTimeKind.Utc);foreach(var at in new[]{start.AddTicks(-1),start,start.AddDays(1).AddTicks(-1),start.AddDays(1)}){var item=await New();foreach(var action in new[]{OrderAction.Confirm,OrderAction.Dispatch,OrderAction.Complete})item=await orders.Execute(new(item,action));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE dbo.DON_HANG SET CompletedAt={at} WHERE Id={item.Id}");await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE dbo.THANH_TOAN SET CollectedAt={at} WHERE OrderId={item.Id}");}var read=await reports.Read("revenue",day,day);Check(read.Revenue==19200000&&read.Orders==2&&read.Daily.Single().Day==day&&read.Daily.Single().Revenue==19200000,"UTC+7 inclusive report boundary mismatch");});
        var peer=new Account{Username="admin-w6-peer-qa",Role="ADMIN",Active=true};peer.PasswordHash=new PasswordHasher<Account>().HashPassword(peer,qa.Password);db.Accounts.Add(peer);await db.SaveChangesAsync();using var second=qa.Api();await second.LoginAsync(peer.Username,qa.Password);
        await Step("WIN.FLOW.03","two distinct Admin accounts real gated contention then refresh; no overwrite",async()=>{row=await New();var stale=row;var one=new OrderOperation(row,OrderAction.Confirm);var two=new OrderOperation(row,OrderAction.Cancel,"Tranh chấp QA");async Task<string> Attempt(OrdersWorkspace work,OrderOperation op){try{await work.Execute(op);return "SUCCESS";}catch(AdminApiException e){return e.Code;}}gate.Enabled=true;var first=Attempt(orders,one);var otherWork=new OrdersWorkspace(second);var other=Attempt(otherWork,two);try{await gate.Ready.Task.WaitAsync(TimeSpan.FromSeconds(20));Check(gate.Arrivals==2&&gate.Connections.Count==2&&!first.IsCompleted&&!other.IsCompleted,"Requests did not contend");gate.Release.TrySetResult();var results=await Task.WhenAll(first,other);Check(results.Count(x=>x=="SUCCESS")==1&&results.Count(x=>x=="CONCURRENT_UPDATE")==1,"Race result wrong");var loser=one.NeedsReadback?await orders.Resolve(one):await otherWork.Resolve(two);Check(loser.Version!=stale.Version&&loser.Status is "DA_XAC_NHAN" or "DA_HUY","Conflict not refreshed");}finally{gate.Enabled=false;gate.Release.TrySetResult();}});
        await Step("WIN.FLOW.04","expired draft save401; second write blocked before HTTP",async()=>{var count=await db.Purchases.CountAsync();await db.Sessions.Where(x=>x.AccountId==peer.Id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.ExpiresAt,DateTime.UtcNow.AddMinutes(-1)));var ended=0;second.SessionEnded+=()=>ended++;foreach(var attempt in Enumerable.Range(0,2)){try{await new PurchaseDraftSession(second).Save(supplier.Id,[new(a,2,8000000)]);throw new InvalidOperationException("Expired write accepted");}catch(AdminApiException e){Check(e.Code=="UNAUTHORIZED","Expiry error wrong");}}Check(ended==1&&second.Identity is null&&await db.Purchases.CountAsync()==count,"Expired session wrote draft");});
        await Step("WIN.FLOW.05","absolute stock count and explicit low threshold",async()=>{var snapshot=await supply.StockRow(b,"W6-B");await supply.Adjust(new(snapshot,3,"Kiểm kê W6 QA"));var metric=await reports.LowStock(3);Check(metric.Value==1&&(await supply.StockRow(b,"W6-B")) is {OnHand:3,Reserved:0,Available:3},"Low-stock metric wrong");});
        await Step("WIN.A22.07","all failed pages; page2 failure must not return partial count",async()=>{var stock=await supply.StockRow(a,"W6-A");await supply.Adjust(new(stock,200,"QA many-page fixture"));for(var i=0;i<105;i++){var failed=await New();failed=await orders.Execute(new(failed,OrderAction.Confirm));failed=await orders.Execute(new(failed,OrderAction.Dispatch));failed=await orders.Execute(new(failed,OrderAction.Fail,"QA failed pagination"));if(i%10==0)await orders.Execute(new(failed,OrderAction.ReceiveReturn));}var metric=await reports.Unreceived();Check(metric.Value==94&&probe.Paths.Any(x=>x.Contains("status=GIAO_THAT_BAI")&&x.Contains("page=2")),"Did not scan all failed pages");probe.FailPageTwo=true;try{await reports.Unreceived();throw new InvalidOperationException("Partial result returned");}catch(AdminApiException e){Check(e.Code=="DATABASE_UNAVAILABLE","Mid-page failure wrong");}finally{probe.FailPageTwo=false;}Check((await reports.Orders("DANG_GIAO")).Value==0,"Independent metric failed");});
        var output=Path.Combine(QaBackend.Root,".artifacts","admin-w6");Directory.CreateDirectory(output);await File.WriteAllTextAsync(Path.Combine(output,"sql-results.json"),JsonSerializer.Serialize(new{qaOnly=true,realBackend=true,checks=records.Count,records,http=probe.Paths},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{records.Count} admin W6 report/flow checks passed.");
    }
    private sealed record Created(long Id);
    private sealed class ReportProbe:DelegatingHandler
    {
        public List<string> Paths { get; }=[];public bool FailPageTwo;
        protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){var path=request.RequestUri!.PathAndQuery;if(request.Method==HttpMethod.Get)Paths.Add(path);if(FailPageTwo&&path.Contains("status=GIAO_THAT_BAI")&&path.Contains("page=2"))return new(HttpStatusCode.ServiceUnavailable){Content=JsonContent.Create(new{code="DATABASE_UNAVAILABLE"})};return await base.SendAsync(request,ct);}
    }
}
